{"title":"Improving cross-document event coreference resolution by discourse coherence and structure","url":"https://www.sciencedirect.com/science/article/pii/S0306457325000275","doi":"10.1016/j.ipm.2025.104085","authors":["Xinyu Chen","Peifeng Li","Qiaoming Zhu"],"year":2025,"abstract":"Proposes Event-oriented Cross-Document Coherence Enhancement to construct coherent textual context for event mentions that appear in different documents, then exploits rhetorical discourse structure to obtain global interaction information. The method is evaluated on ECB+ and GVC for clustering mentions of the same real-world event.","venue":"Information Processing & Management"}
{"title":"Cross-Document Event Coreference Resolution on Discourse Structure","url":"https://aclanthology.org/2023.emnlp-main.294/","doi":"10.18653/v1/2023.emnlp-main.294","authors":["Xinyu Chen","Sheng Xu","Peifeng Li","Qiaoming Zhu"],"year":2023,"abstract":"Treats cross-document event coreference as clustering event mentions that refer to the same real-world events. It introduces document-level rhetorical structure and shortest dependency paths between event mentions to supplement local mention features and evaluates the method on ECB+.","venue":"EMNLP"}
{"title":"Synergetic Event Understanding: A Collaborative Approach to Cross-Document Event Coreference Resolution with Large Language Models","url":"https://arxiv.org/abs/2406.02148","arxiv_id":"2406.02148","doi":"10.18653/v1/2024.acl-long.164","authors":["Qingkai Min","Qipeng Guo","Xiangkun Hu","Songfang Huang","Zheng Zhang","Yue Zhang"],"year":2024,"abstract":"Addresses clustering event mentions across documents that refer to the same real-world event. An LLM first produces richer event understanding and summaries, while a task-specific smaller model learns refined event representations; the approach is evaluated across multiple cross-document event-coreference datasets.","venue":"ACL"}
{"title":"Multimodal Cross-Document Event Coreference Resolution Using Linear Semantic Transfer and Mixed-Modality Ensembles","url":"https://arxiv.org/abs/2404.08949","arxiv_id":"2404.08949","authors":["Abhijnan Nath","Huma Jamil","Shafiuddin Rehan Ahmed","George Arthur Baker","Rahul Ghosh","James H. Martin","Nathaniel Blanchard","Nikhil Krishnaswamy"],"year":2024,"abstract":"Studies whether distinct event mentions in a multi-document corpus refer to the same underlying occurrence and tests visual evidence in addition to text. It augments ECB+ with event-centric images and evaluates multimodal fusion, cross-modal linear mapping, and mixed-modality ensembles on ECB+ and AIDA Phase 1.","venue":"LREC-COLING"}
{"title":"Generating Harder Cross-document Event Coreference Resolution Datasets using Metaphoric Paraphrasing","url":"https://arxiv.org/abs/2407.11988","arxiv_id":"2407.11988","doi":"10.18653/v1/2024.acl-short.27","authors":["Shafiuddin Rehan Ahmed","Zhiyong Eric Wang","George Arthur Baker","Kevin Stowe","James H. Martin"],"year":2024,"abstract":"Introduces ECB+META, a lexically more diverse variant of ECB+ that preserves existing same-event coreference links while paraphrasing event expressions. Experiments show that systems performing strongly on ECB+ degrade on the harder corpus, providing evidence that lexical overlap can exaggerate apparent event-identity performance.","venue":"ACL"}
{"title":"Revisiting Joint Modeling of Cross-document Entity and Event Coreference Resolution","url":"https://arxiv.org/abs/1906.01753","arxiv_id":"1906.01753","doi":"10.18653/v1/P19-1409","authors":["Shany Barhom","Vered Shwartz","Alon Eirew","Michael Bugert","Nils Reimers","Ido Dagan"],"year":2019,"abstract":"Jointly resolves entity and event coreference across documents using mention spans, surrounding context, and predicate-argument relations. Its analysis on ECB+ finds that the mention span, context, and relations to other mentions all contribute to event-coreference decisions.","venue":"ACL"}
{"title":"Joint Entity and Event Coreference Resolution across Documents","url":"https://aclanthology.org/D12-1045/","authors":["Heeyoung Lee","Marta Recasens","Angel Chang","Mihai Surdeanu","Dan Jurafsky"],"year":2012,"abstract":"Introduces an iterative system that cautiously merges entity and event clusters across comparable documents. Information propagates between event and entity clusters through semantic-role dependencies, allowing event arguments and their relations to inform same-instance decisions.","venue":"EMNLP-CoNLL"}
{"title":"A Hierarchical Distance-dependent Bayesian Model for Event Coreference Resolution","url":"https://arxiv.org/abs/1504.05929","arxiv_id":"1504.05929","doi":"10.1162/tacl_a_00155","authors":["Bishan Yang","Claire Cardie","Peter Frazier"],"year":2015,"abstract":"Uses a feature-rich learnable pairwise distance as a Bayesian prior for nonparametric clustering of event mentions. The model explicitly supports both within- and cross-document event coreference and is evaluated on ECB+.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"Unsupervised Event Coreference Resolution with Rich Linguistic Features","url":"https://aclanthology.org/P10-1143/","authors":["Cosmin Bejan","Sanda Harabagiu"],"year":2010,"abstract":"Applies nonparametric Bayesian clustering with rich linguistic features to open-domain event coreference. The evaluation explicitly covers both within-document and cross-document event coreference, making the work relevant to evidence combination for same-event clustering.","venue":"ACL"}
{"title":"Resolving Event Coreference with Supervised Representation Learning and Clustering-Oriented Regularization","url":"https://arxiv.org/abs/1805.10985","arxiv_id":"1805.10985","doi":"10.18653/v1/S18-2001","authors":["Kian Kenyon-Dean","Jackie Chi Kit Cheung","Doina Precup"],"year":2018,"abstract":"Learns representations of event mentions with clustering-oriented regularization and then forms event chains through agglomerative clustering. It evaluates both within- and cross-document event coreference on ECB+.","venue":"*SEM"}
{"title":"Event Coreference Resolution by Iteratively Unfolding Inter-dependencies among Events","url":"https://arxiv.org/abs/1707.07344","arxiv_id":"1707.07344","authors":["Prafulla Kumar Choubey","Ruihong Huang"],"year":2017,"abstract":"Uses separate classifiers for within-document and cross-document event-coreference links because their feature distributions differ. It alternates clustering stages, combines arguments after merges, and uses relations among event chains to drive additional merges on ECB+.","venue":"EMNLP"}
{"title":"Position-aware end-to-end cross-document event coreference resolution for Dutch","url":"https://www.sciencedirect.com/science/article/pii/S2949719125000603","doi":"10.1016/j.nlp.2025.100184","authors":["Loic De Langhe","Orphée De Clercq","Veronique Hoste"],"year":2025,"abstract":"Presents an end-to-end cross-document event-coreference system combining positional knowledge and graph representations. It is evaluated on a large Dutch event-coreference dataset and includes qualitative and quantitative analysis of errors in predicted coreference chains.","venue":"Natural Language Processing Journal"}
{"title":"Enhancing Cross-Document Event Coreference Resolution by Discourse Structure and Semantic Information","url":"https://aclanthology.org/2024.lrec-main.523/","authors":["Qiang Gao","Bobo Li","Zixiang Meng","Yunlong Li","Jun Zhou","Fei Li","Chong Teng","Donghong Ji"],"year":2024,"abstract":"Augments cross-document event-coreference evidence with rhetorical document structure and cross-document lexical chains, while noting that argument features such as location, time, agent, and patient are commonly used evidence. It evaluates same-event clustering on English data and a newly constructed Chinese cross-document event-coreference dataset.","venue":"LREC-COLING"}
{"title":"Linear Cross-document Event Coreference Resolution with X-AMR","url":"https://arxiv.org/abs/2404.08656","arxiv_id":"2404.08656","authors":["Shafiuddin Rehan Ahmed","George Arthur Baker","Evi Judge","Michael Reagan","Kristin Wright-Bettner","Martha Palmer","James H. Martin"],"year":2024,"abstract":"Represents individual event mentions with cross-document AMR graphs and uses a multi-hop algorithm to linearize event-coreference decisions that otherwise require pairwise comparisons. The work also uses the representation to assess LLM event-coreference judgments against human annotations.","venue":"LREC-COLING"}
{"title":"Employing Discourse Coherence Enhancement to Improve Cross-Document Event and Entity Coreference Resolution","url":"https://aclanthology.org/2025.acl-long.1134/","authors":["Xinyu Chen","Peifeng Li","Qiaoming Zhu"],"year":2025,"abstract":"Introduces Cross-Document Discourse Coherence Enhancement to create coherent context between mentions that originate in separate documents. The generated coherent text is then used to represent mentions and resolve cross-document event or entity coreference.","venue":"ACL"}
{"title":"Argument centric causal intervention for cross document event coreference resolution","url":"https://www.nature.com/articles/s41598-025-32765-6","doi":"10.1038/s41598-025-32765-6","authors":["Long Yao","Wenzhong Yang","Yabo Yin","Fuyuan Wei","Liejun Wang","Xiaoming Tao"],"year":2025,"published":"2025-12-17","abstract":"Targets the binary question of whether cross-document event mentions refer to the same real-world occurrence. The method uses causal intervention and counterfactual trigger perturbations to reduce reliance on superficial lexical matches and isolate evidence contributed by event arguments, with evaluation on ECB+ and GVC.","venue":"Scientific Reports"}
{"title":"Multimodal Cross-Document Event Coreference Resolution via Contrastive Evidence Reasoning","url":"https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7284343","doi":"10.2139/ssrn.7284343","authors":["Xue Qiao","Fei Li","Yanfeng Hu","Shuang Gu","Chen Peng","Zhiwei Xiong"],"year":2026,"published":"2026-08-14","abstract":"Reframes cross-document event coreference as abductive reasoning between competing same-event and different-event hypotheses. It selects between them using explanatory coherence, parsimony, and consistency, combines multimodal retrieval with incremental graph clustering, and evaluates on ECB+, AIDA Phase 1, and WEC-Eng.","venue":"SSRN"}
{"title":"Identity, non-identity, and near-identity: Addressing the complexity of coreference","url":"https://www.sciencedirect.com/science/article/pii/S0024384111000325","doi":"10.1016/j.lingua.2011.02.004","authors":["Marta Recasens","Eduard Hovy","Antonia Martí"],"year":2011,"abstract":"Argues that reference identity is not always adequately modeled as a simple binary relation and develops a continuum from full identity through near-identity to non-identity. It discusses granularity, individuation, and identity criteria, providing transferable semantics for distinguishing strict continuation from related but non-identical instances.","venue":"Lingua"}
{"title":"Detecting Subevent Structure for Event Coreference Resolution","url":"https://aclanthology.org/L14-1725/","authors":["Jun Araki","Zhengzhong Liu","Eduard Hovy","Teruko Mitamura"],"year":2014,"abstract":"Separates full event coreference from partial coreference expressed through hierarchical subevent relations. A multiclass model detects subevent relations in addition to full coreference, directly informing the distinction between event identity and part-of relations.","venue":"LREC"}
{"title":"Using a sledgehammer to crack a nut? Lexical diversity and event coreference resolution","url":"https://aclanthology.org/L14-1646/","authors":["Agata Cybulska","Piek Vossen"],"year":2014,"abstract":"Shows that the original EventCorefBank often contains only one seminal event per domain, making event identity easier because of limited event and lexical diversity. The authors construct ECB+ with different instances of event types already represented in ECB, making it useful for testing whether systems distinguish same-type events from the same concrete event.","venue":"LREC"}
{"title":"Event-case correlation for process mining using probabilistic optimization","url":"https://arxiv.org/abs/2206.10009","arxiv_id":"2206.10009","doi":"10.1016/j.is.2023.102167","authors":["Dina Bayomie","Claudio Di Ciccio","Jan Mendling"],"year":2023,"abstract":"Addresses event logs lacking case identifiers, including logs assembled from different systems, by grouping events into inferred process cases. The method combines process-model compatibility with event data constraints in a probabilistic optimization objective and evaluates the resulting case assignments on real-life datasets.","venue":"Information Systems"}
{"title":"A Probabilistic Approach to Event-Case Correlation for Process Mining","url":"https://doi.org/10.1007/978-3-030-33223-5_12","doi":"10.1007/978-3-030-33223-5_12","authors":["Dina Bayomie","Claudio Di Ciccio","Marcello La Rosa","Jan Mendling"],"year":2019,"abstract":"Studies how to infer case membership when events collected from different systems lack explicit case identifiers. Its probabilistic optimization maps each event to a case using an underlying process model and temporal behavior, making it transferable to longitudinal work-matter assignment.","venue":"International Conference on Conceptual Modeling"}
{"title":"Online correlation for unlabeled process events: A flexible CEP-based approach","url":"https://www.sciencedirect.com/science/article/pii/S0306437922000333","doi":"10.1016/j.is.2022.102031","authors":["Iman M. A. Helal","Ahmed Awad"],"year":2022,"abstract":"Correlates unlabeled events arriving in a stream to process-case identifiers rather than assuming case IDs are already available. A probabilistic online method can associate one event with zero or more candidate cases and accepts runtime constraints to reduce the correlation space; it is evaluated on real and synthetic logs.","venue":"Information Systems"}
{"title":"A Study of Retrospective and On-Line Event Detection","url":"https://doi.org/10.1145/290941.290953","doi":"10.1145/290941.290953","authors":["Yiming Yang","Thomas Pierce","Jaime G. Carbonell"],"year":1998,"abstract":"Studies retrospective and online event detection in chronologically ordered news, including the online problem of deciding whether incoming material belongs to an already observed event or signals a new one. This provides transferable design evidence for NEW-versus-existing assignment in a stream.","venue":"SIGIR"}
{"title":"Learning approaches for detecting and tracking news events","url":"https://doi.org/10.1109/5254.784083","doi":"10.1109/5254.784083","authors":["Yiming Yang","Jaime G. Carbonell","Ralf D. Brown","Thomas Pierce","Brian T. Archibald","Xin Liu"],"year":1999,"abstract":"Adapts information-retrieval and machine-learning methods to detecting novel events in chronologically ordered news streams and tracking already identified events over time. The task structure provides transferable evidence for distinguishing new event identity from continuation.","venue":"IEEE Intelligent Systems and their Applications"}
{"title":"A System for new event detection","url":"https://doi.org/10.1145/860435.860495","doi":"10.1145/860435.860495","authors":["Thorsten Brants","Francine Chen"],"year":2003,"abstract":"Presents a system for new-event detection in a stream of news stories, where an incoming story must be distinguished from stories about previously observed events. The formulation is transferable to rejecting all existing clusters and creating a new identity.","venue":"SIGIR"}
{"title":"Text Classification and Named Entities for New Event Detection","url":"https://doi.org/10.1145/1008992.1009044","doi":"10.1145/1008992.1009044","authors":["Giridhar Kumaran","James Allan"],"year":2004,"abstract":"Investigates new-event detection using text classification and named-entity information and develops a multistage system that improves over single-stage baselines. Its experiments show that named entities are useful only in some circumstances rather than constituting sufficient event-identity evidence by themselves.","venue":"SIGIR"}
{"title":"Using Names and Topics for New Event Detection","url":"https://aclanthology.org/H05-1016/","doi":"10.3115/1220575.1220591","authors":["Giridhar Kumaran","James Allan"],"year":2005,"abstract":"Studies new-event detection in chronologically ordered news using separate similarities based on names, topics, and full text. It is useful as transfer evidence that entity names and topical content can contribute to a new-versus-existing decision without themselves defining same-event identity.","venue":"HLT-EMNLP"}
{"title":"New event detection and topic tracking in Turkish","url":"https://onlinelibrary.wiley.com/doi/10.1002/asi.21264","doi":"10.1002/asi.21264","authors":["Fazli Can","Seyit Kocberber","Ozgur Baglioglu","Suleyman Kardas","H. Cagdas Ocalan","Erkan Uyar"],"year":2010,"published":"2010-01-12","abstract":"Evaluates both detection of first stories for new events and tracking of subsequent stories in a temporally ordered news stream. It also examines combining confidence scores from different similarity measures, making it relevant to evidence fusion for new-versus-existing event decisions.","venue":"Journal of the American Society for Information Science and Technology"}
{"title":"Model-based Clustering of Short Text Streams","url":"https://www.kdd.org/kdd2018/accepted-papers/view/model-based-clustering-of-short-text-streams","doi":"10.1145/3219819.3220094","authors":["Jianhua Yin","Daren Chao","Zhongkun Liu","Wei Zhang","Xiaohui Yu","Jianyong Wang"],"year":2018,"abstract":"Proposes one-pass short-text stream clustering that handles a changing stream with a nonparametric mixture model. Its MStreamF variant includes forgetting rules that remove outdated clusters, providing transferable mechanisms for online cluster creation and maintenance rather than static assignment alone.","venue":"KDD"}
{"title":"Dynamic clustering for short text stream based on Dirichlet process","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8313119/","doi":"10.1007/s10489-021-02263-z","authors":["Wanyin Xu","Yun Li","Jipeng Qiang"],"year":2022,"abstract":"Uses a Dirichlet process for dynamic short-text clustering so that incoming text may join an existing cluster or generate a new one without fixing the number of clusters in advance. The model also updates and removes outdated topic information to accommodate stream drift.","venue":"Applied Intelligence"}
{"title":"Lifelong Learning Augmented Short Text Stream Clustering Method","url":"https://doi.org/10.1109/ACCESS.2021.3078096","doi":"10.1109/ACCESS.2021.3078096","authors":["Jipeng Qiang","Wanyin Xu","Yun Li","Yunhao Yuan","Yi Zhu"],"year":2021,"published":"2021-05-06","abstract":"Introduces a one-pass short-text stream clustering method augmented with episodic memory and sparse experience replay. Periodic replay of recent observations updates cluster features, providing a transferable mechanism for maintaining continuity under evolving streams.","venue":"IEEE Access"}
{"title":"Incremental entity resolution on rules and data","url":"https://www.vldb.org/vldb_journal/index.php/component/article_manager/article/1270","doi":"10.1007/s00778-013-0315-0","authors":["Steven Euijong Whang","Hector Garcia-Molina"],"year":2014,"abstract":"Studies how entity-resolution results can be maintained when matching rules or incoming data evolve instead of recomputing resolution from scratch. It develops incremental techniques for match-based clustering, distance-based clustering, and pairwise matching, making it relevant to correction and identity preservation over time.","venue":"The VLDB Journal"}
{"title":"Improved suffix blocking for record linkage and entity resolution","url":"https://www.sciencedirect.com/science/article/pii/S0169023X16300714","doi":"10.1016/j.datak.2018.07.005","authors":["Amin Allam","Spiros Skiadopoulos","Panos Kalnis"],"year":2018,"abstract":"Develops blocking methods for record linkage and entity resolution, including their incremental variants after insertion of a new record. The work is transferable to scalable candidate generation before a more expensive same-instance identity decision.","venue":"Data & Knowledge Engineering"}
{"title":"Probabilistic record linkage is a valid and transparent tool to combine databases without a patient identification number","url":"https://pubmed.ncbi.nlm.nih.gov/17689804/","doi":"10.1016/j.jclinepi.2006.11.021","authors":["Nora Méray","Johannes B Reitsma","Anita C J Ravelli","Gouke J Bonsel"],"year":2007,"abstract":"Combines probabilistic and deterministic linkage where databases lack a shared identifier. Agreement on corresponding variables contributes rewards and disagreement contributes penalties estimated from observed agreement patterns, providing transferable evidence-combination mechanics for match versus non-match decisions.","venue":"Journal of Clinical Epidemiology"}
{"title":"Selective Classification Under Distribution Shifts","url":"https://arxiv.org/abs/2405.05160","arxiv_id":"2405.05160","authors":["Hengyue Liang","Le Peng","Ju Sun"],"year":2024,"abstract":"Extends selective classification so a model can abstain on likely errors when deployment data differ from the training distribution. The framework explicitly considers in-distribution, label-shifted or out-of-distribution, and covariate-shifted samples, directly informing confidence-based abstention under nonstationarity.","venue":"Transactions on Machine Learning Research"}
{"title":"Classification with reject option in text categorisation systems","url":"https://doi.org/10.1109/ICIAP.2003.1234113","doi":"10.1109/ICIAP.2003.1234113","authors":["Giorgio Fumera","Ignazio Pillai","Fabio Roli"],"year":2003,"abstract":"Adapts the reject option specifically to text categorisation so that a classifier can withhold decisions judged insufficiently reliable. It evaluates rejection thresholds on the Reuters text corpus and demonstrates the tradeoff between automatic coverage and classification reliability.","venue":"International Conference on Image Analysis and Processing"}
{"title":"A Two-Stage Classifier with Reject Option for Text Categorisation","url":"https://doi.org/10.1007/978-3-540-27868-9_84","doi":"10.1007/978-3-540-27868-9_84","authors":["Giorgio Fumera","Ignazio Pillai","Fabio Roli"],"year":2004,"abstract":"Investigates reject decisions for text categorisation when first-stage evidence is insufficiently reliable. Rejected documents are routed to a second classifier, and the architecture is evaluated on a real Reuters text-categorisation task.","venue":"Joint IAPR International Workshops on Structural, Syntactic, and Statistical Pattern Recognition"}
{"title":"Classification with a Reject Option using a Hinge Loss","url":"https://jmlr.org/papers/v9/bartlett08a.html","authors":["Peter L. Bartlett","Marten H. Wegkamp"],"year":2008,"abstract":"Formalizes binary classification in which the classifier may decline to classify an observation at a specified cost. It develops a convex surrogate loss and analyzes statistical consistency and error-versus-rejection behavior, providing transferable foundations for an explicit abstain decision.","venue":"Journal of Machine Learning Research"}
{"title":"Classification with reject option","url":"https://onlinelibrary.wiley.com/doi/10.1002/cjs.5550340410","doi":"10.1002/cjs.5550340410","authors":["Radu Herbei","Marten H. Wegkamp"],"year":2006,"abstract":"Studies binary classification with a third reject outcome for observations whose conditional class probabilities make automatic classification uncertain. The paper develops theory for plug-in rules and empirical-risk minimizers under this three-way decision setting.","venue":"Canadian Journal of Statistics"}
{"title":"Classification Methods with Reject Option Based on Convex Risk Minimization","url":"https://www.jmlr.org/papers/v11/yuan10a.html","authors":["Ming Yuan","Marten Wegkamp"],"year":2010,"abstract":"Studies binary classification in which a decision may be withheld at lower cost than a misclassification. It develops convex surrogate-risk methods, consistency conditions, and excess-risk bounds, offering transferable theory for confidence thresholds and abstention.","venue":"Journal of Machine Learning Research"}
{"title":"Harvesting Events from Multiple Sources: Towards a Cross-Document Event Extraction Paradigm","url":"https://aclanthology.org/2024.findings-acl.114/","doi":"10.18653/v1/2024.findings-acl.114","authors":["Qiang Gao","Zixiang Meng","Bobo Li","Jun Zhou","Fei Li","Chong Teng","Donghong Ji"],"year":2024,"abstract":"Defines a cross-document event-extraction pipeline that explicitly includes event coreference resolution before normalization and entity-role resolution, allowing information about one event to be integrated across sources. It introduces the CLES dataset with cross-document events and evaluates the complete pipeline, making it relevant as adjacent evidence for multi-source event identity.","venue":"Findings of ACL"}
===END llm_candidates.jsonl===
